def sum_to(n):
    if n <= 0:
        return 0
    return n + sum_to(n - 1)

def _digit_sum(n):
    if n < 10:
        return n
    return n % 10 + _digit_sum(n // 10)

def digital_root(n):
    if n < 10:
        return n
    return digital_root(_digit_sum(n))

